// Enclosure density index — record JAH-GPCS-RAIDENCLOSURE-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"bays": 2, "max_tb": 40, "price_usd": 150};
var value = (m.bays*m.max_tb/m.price_usd*100);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPCS-RAIDENCLOSURE-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPCS-RAIDENCLOSURE-000001|' + value.toFixed(2) + ' density index');

